// Aceita o lead do jeito que a origem mandar.
//
// POR QUE OLHA EM TRÊS LUGARES: o Bitrix manda os dados do negócio na QUERY
// STRING da URL (?Nome=...&Telefone=...) e usa o corpo só para os metadados
// dele (document_id, auth). Um formulário comum manda tudo no corpo. Então
// juntamos query + body + raiz, com a query na frente — é onde o Bitrix põe o
// que interessa.
const entrada = $input.first().json;
const b = { ...(entrada.body ?? {}), ...(entrada.query ?? {}), ...entrada };

const txt = (...chaves) => {
  for (const k of chaves) {
    const v = b[k];
    if (v != null && typeof v !== 'object' && String(v).trim() !== '') return String(v).trim();
  }
  return null;
};

// O QS deduplica por telefone, então "(62) 99999-0001" e "5562999990001"
// precisam virar a MESMA coisa — senão o mesmo cliente entra duas vezes.
function telefone(v) {
  let d = String(v ?? '').replace(/\D/g, '');
  if (!d) return null;
  d = d.replace(/^0+/, '');           // tira 0 de operadora
  if (!d.startsWith('55')) d = '55' + d;
  // 55 + DDD(2) + número(8 ou 9)
  return (d.length === 12 || d.length === 13) ? d : null;
}

// O Bitrix manda Nome e Sobrenome separados.
const nome = txt('full_name', 'nome', 'Nome', 'NOME', 'name', 'cliente');
const sobrenome = txt('last_name', 'sobrenome', 'Sobrenome');
const nomeCompleto = [nome, sobrenome].filter(Boolean).join(' ') || null;

const saida = {
  full_name:    nomeCompleto,
  phone:        telefone(txt('phone', 'telefone', 'Telefone', 'whatsapp', 'WhatsApp', 'celular', 'Celular')),
  email:        txt('email', 'e-mail', 'E-mail', 'Email', 'EMAIL'),
  // Fonte aparece no card do lead — é como a SDR sabe de onde a pessoa veio.
  segment:      txt('segment', 'fonte', 'Fonte', 'origem', 'Origem') ?? 'Resgate',
  source:       txt('source') ?? 'resgate',
  // Temperatura: o Bitrix chama de LeadScoring ("Quente", "Morno", "Frio").
  lead_score:   txt('lead_score', 'LeadScoring', 'leadScoring', 'temperatura', 'Temperatura'),
  city:         txt('city', 'cidade', 'Cidade'),
  state:        txt('state', 'estado', 'uf', 'UF'),
  company_name: txt('company_name', 'empresa', 'Empresa'),
  // ID do negócio no Bitrix: é o que impede o mesmo card de virar dois leads.
  bitrix_id:    txt('bitrix_id', 'id_bitrix', 'ID', 'id'),
};

// Sem nenhum jeito de identificar a pessoa, o QS recusaria com um erro genérico.
// Melhor falhar aqui, dizendo exatamente o que chegou — foi assim que
// descobrimos que o Bitrix manda tudo na query e nada no corpo.
if (!saida.full_name && !saida.phone && !saida.email) {
  throw new Error(
    'Nenhum dado do lead veio na chamada. Campos recebidos: ' +
    (Object.keys(b).filter((k) => typeof b[k] !== 'object').join(', ') || '(nenhum)') +
    '. No Bitrix, confira se o webhook está mandando Nome/Telefone/E-mail na URL.'
  );
}

return [{ json: saida }];

// Traduz a resposta do QS pra algo legível no histórico do n8n.
const r = $input.first().json;
const status = r.statusCode ?? 0;
const corpo = r.body ?? {};

let resultado, detalhe;
if (status === 200 && corpo.success) {
  resultado = corpo.deduped ? 'ja_existia' : 'criado';
  detalhe = corpo.deduped
    ? 'Esse lead JÁ estava no QS. Nada foi alterado — ele continua na cadência em que estava.'
    : `Lead criado com ${corpo.tasks_created} atividades na cadência de resgate.`;
} else if (status === 401) {
  resultado = 'erro';
  detalhe = 'Segredo recusado. Confira o header x-lead-secret no nó "Enviar para o QS".';
} else if (status === 400) {
  resultado = 'erro';
  detalhe = corpo.error || 'Faltou telefone, e-mail ou nome.';
} else {
  resultado = 'erro';
  detalhe = corpo.error || `Falha inesperada (HTTP ${status}).`;
}

return [{ json: {
  resultado,
  detalhe,
  lead_id: corpo.lead_id ?? null,
  lista: corpo.lista ?? null,
  cadence_id: corpo.cadence_id ?? null,
} }];
